import{_ as a,o as t,c as r,ak as n}from"./chunks/framework.B8jO0odJ.js";const h=JSON.parse('{"title":"Current GDD visual supplements","description":"Created October 22, 2026 with the built-in imagegen tool (no CLI fallback). The two original Chainy storyboards are style references. These new concepts supplement both curren","frontmatter":{"title":"Current GDD visual supplements","description":"Created October 22, 2026 with the built-in imagegen tool (no CLI fallback). The two original Chainy storyboards are style references. These new concepts supplement both curren","source":"docs/media/gdd/current-visuals/README.md","category":"Other documents","sourceUpdated":"2026-10-22T19:09:09+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/media/gdd/current-visuals/readme.md","filePath":"content/docs/media/gdd/current-visuals/readme.md"}'),o={name:"content/docs/media/gdd/current-visuals/readme.md"};function s(i,e,l,c,d,u){return t(),r("div",null,[...e[0]||(e[0]=[n(`<div><h1 id="current-gdd-visual-supplements">Current GDD visual supplements<a class="header-anchor" href="#current-gdd-visual-supplements" aria-label="Link to this section">​</a></h1><p>Created October 22, 2026 with the built-in image_gen tool (no CLI fallback). The two original Chainy storyboards are style references. These new concepts supplement both current PDF editions; they are not implementation evidence or approved gameplay rules.</p><ul><li><a href="/Chainy-Docs/attachments/docs/media/gdd/current-visuals/exploration-guide.png">Exploration and guide</a>: rounded 3D island, blue-haired yellow-clad explorer and friendly robot. Scene scale, props and camera are illustrative.</li><li><a href="/Chainy-Docs/attachments/docs/media/gdd/current-visuals/mini-game-concepts.png">Mini-game concepts</a>: separate Quiz, Wordle and BlockMatch panels. DATA does not fix word length. Tile count, matching rules, colors and layout remain illustrative. The green Yes button must not be copied as an answer-revealing cue; neutral answer styling is required before submission. The board illustrates tile appearance, not an approved educational matching rule.</li></ul><p>Original references remain the art authority. The flat BlockForge reference is gameplay context only and was not used for styling. Documentation images are not ready-to-import interactive Unity screens. Luis owns production art; Miguel owns UI implementation; Sean owns authored project documentation; Sherwin approves design choices.</p><h2 id="exact-generation-prompts">Exact generation prompts<a class="header-anchor" href="#exact-generation-prompts" aria-label="Link to this section">​</a></h2><h3 id="exploration">Exploration<a class="header-anchor" href="#exploration" aria-label="Link to this section">​</a></h3><pre><code class="language-text">Use case: stylized-concept. Create a new wide landscape 3D game-design illustration for Chainy based on the two attached reference storyboards (style references only). Match their cute rounded toy-like proportions, blue-haired explorer with yellow coat and yellow backpack, gold circular hair detail, friendly white robot with black screen face and cyan eyes, matte rounded voxel island scenery, blue/green foreground and subtle violet technology buildings. One cohesive landscape game view, not a collage. Explorer seen three-quarter from behind on a grassy stone path, robot facing explorer beside a small learning station displaying a book and blue data cube. Open welcoming compact explorable island area. Camera slightly elevated third-person. Generous clear foreground, readable silhouettes, soft warm daylight, polished reference-consistent 3D. No text, UI, currency, trophies, combat, chains to construct, pets, or map locks. This illustrates exploration and guide interaction for offline educational learning, not a finished game screenshot. Aspect ratio about 16:9. Use the provided files as visual references.
</code></pre><h3 id="mini-games">Mini-games<a class="header-anchor" href="#mini-games" aria-label="Link to this section">​</a></h3><pre><code class="language-text">Use case: ui-mockup. Create a polished wide landscape three-panel visual concept sheet for Chainy educational mini-games. The two input storyboards are STYLE references only: match rounded 3D toy-like blue-haired yellow-coated explorer, friendly cyan-eyed white screen-faced robot, blue/green and violet island scenery. Three equal-width panels side by side with clear gutters, each a different activity UI, large legible minimal type. Left header &#39;QUIZ&#39;: friendly robot beside a question card &#39;Can AI make mistakes?&#39; and two large answer buttons &#39;Yes&#39; and &#39;No&#39;; neutral state neither selected. Middle header &#39;WORDLE&#39;: large cream letter tiles spell &#39;D A T A&#39; in a single row with no correctness colors; underneath a compact card reads &#39;Information we can use&#39;. This is an example word, no attempts counter or fixed guess grid. Right header &#39;BLOCKMATCH&#39;: small neat square board of colorful rounded tiles with clearly distinguishable geometric symbols (circles, triangles, squares); no arrows, no selected move, no score, no timer. Board is illustrative only and should not show an implied winning state. Each panel has a soft 3D island backdrop and a simple rounded blue frame. Small consistent footer across bottom &#39;VISUAL CONCEPT - RULES TO BE CONFIRMED&#39;. Clear professional GDD plate, about 16:9. No coins, stars, health, weapons, maps, online icons, purchase options or extra game modes. Preserve reference character proportions; not flat vector art. Panels are separate activities, not simultaneously active gameplay.
</code></pre></div>`,1)])])}const m=a(o,[["render",s]]);export{h as __pageData,m as default};
